import re
from decimal import Decimal, InvalidOperation, ROUND_CEILING


_DURATION_TERM = re.compile(r"(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)(?:ms|[smhd])")
_DURATION_UNITS = {
    "ms": Decimal(1),
    "s": Decimal(1000),
    "m": Decimal(60000),
    "h": Decimal(3600000),
    "d": Decimal(86400000),
}


def parse_duration(text):
    if not isinstance(text, str) or not text.strip():
        raise ValueError("duration must be a non-empty string")

    total = Decimal(0)
    position = 0
    length = len(text)

    while position < length:
        while position < length and text[position] in " \t\n\r\v\f":
            position += 1
        if position == length:
            break

        match = _DURATION_TERM.match(text, position)
        if match is None:
            raise ValueError("invalid duration")

        term = match.group(0)
        unit = "ms" if term.endswith("ms") else term[-1]
        number = term[:-len(unit)]
        try:
            total += Decimal(number) * _DURATION_UNITS[unit]
        except InvalidOperation as exc:
            raise ValueError("invalid duration") from exc
        position = match.end()

        if position < length and text[position] not in " \t\n\r\v\f" and not _DURATION_TERM.match(text, position):
            raise ValueError("invalid duration")

    return int(total.to_integral_value(rounding=ROUND_CEILING))

